mapper.select:
SELECT s.id, s.warehouse_id, s.material_id, s.type, s.quantity,
       s.purchase_request_id, s.project_id, s.operator_id, s.created_at,
       pr.code AS purchase_request_code,
       u.name AS operator_name
FROM t_stock_record s
LEFT JOIN t_purchase_request pr ON s.purchase_request_id = pr.id
LEFT JOIN t_user u ON s.operator_id = u.id
WHERE 1=1
AND s.warehouse_id = #{warehouseId}
AND s.material_id = #{materialId}
AND s.type = #{type}
ORDER BY s.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM t_stock_record WHERE 1=1
AND warehouse_id = #{warehouseId}
AND material_id = #{materialId}
AND type = #{type}
